      "replace": "    @pydantic.root_validator
    def _validate_context(cls, values):
        trace_id = values.get("trace_id")
        observation_id = values.get("observation_id")
        dataset_id = values.get("dataset_id")
        dataset_item_id = values.get("dataset_item_id")
        # Validate exclusive contexts
        if dataset_id or dataset_item_id:
            if trace_id or observation_id:
                raise ValueError(
                    "Provide either trace (trace_id) or dataset (dataset_id & dataset_item_id), not both."
                )
            if not (dataset_id and dataset_item_id):
                raise ValueError(
                    "Both dataset_id and dataset_item_id must be provided together."
                )
        else:
            if not trace_id:
                raise ValueError("trace_id is required when dataset context not provided.")
        return values

