  "test": "import pytest
from pydantic import ValidationError
from langfuse.api.media.types.get_media_upload_url_request import GetMediaUploadUrlRequest

def _make_valid_base():
    return {
        "content_type": "image/png",
        "content_length": 10,
        "sha256hash": "0" * 64,
        "field": "input",
    }

def test_valid_trace_context():
    data = _make_valid_base()
    data.update({"trace_id": "trace-123", "observation_id": "obs-456"})
    req = GetMediaUploadUrlRequest(**data)  # should not raise
    assert req.trace_id == "trace-123"
    assert req.observation_id == "obs-456"

def test_invalid_both_contexts_raise():
    data = _make_valid_base()
    data.update({"trace_id": "t1", "dataset_id": "d1", "dataset_item_id": "i1"})
    with pytest.raises(ValidationError):
        GetMediaUploadUrlRequest(**data)

def test_invalid_partial_dataset_context_raise():
    data = _make_valid_base()
    data.update({"dataset_id": "d1"})  # missing dataset_item_id and no trace_id
    with pytest.raises(ValidationError):
        GetMediaUploadUrlRequest(**data)
